9: /* HBUFSZ is the size of the metafile output buffer in
10:    number of short integers.  The metafile buffer should be as
11:    large as is convenient for the target system.  Frames larger
12:    than the buffer will get bufferred into the meta file on disk,
13:    when BUFOPT is 1.  Otherwise multiple buffers of size HBUFSZ
14:    will be allocated as needed. */
15: 
16: #define HBUFSZ 10000000L 
17: #define BUFOPT 0
18: #define pi M_PI
