20: /* Default directory containing the stroke and map data sets.
21:    User can override this default via setenv GADDIR */
22: 
23: /* static char *datad = "/usr/local/lib/grads"; */
24: 
25: 
26: /* Option flag.  If 0, map data set is only read once into a
27:    dynamically allocated memory area.  The memory is held onto
28:    for the next call (about 35K).  If 1, the memory is allocated for
29:    each call and the map data set is read each time.             */
30: /* Lowres map only */
31: 
32: #define MAPOPT 0
