    if (gapystart) {
      PyErr_SetString(PyExc_TypeError, "start error: this method has already been invoked");
      return NULL;
    }

    if (gapyerror) {
      PyErr_SetString(PyExc_TypeError, "start error: prior initialization error");
      return NULL;
    }

