    siz = (int)tupsiz;

    arglist[0] = ganame;
    for (i=0; i<siz; i++) {
      item = PyTuple_GetItem(args,i);

      if (PyUnicode_Check(item) != 1) {
         PyErr_SetString(PyExc_TypeError, "start error: args must be strings");
